link.script:
(function(){'use strict';
if(!window.matchMedia||!window.matchMedia('(hover:hover) and (pointer:fine)').matches)return;
var selector='.kb-mobile-submit-primary,.kb-upload-submit,.btn-glow-primary,.kb-license-accept:not(:disabled),.kb-back-to-top,.kb-checker-compare-dock,.kb-vip-primary-cta,.kb-vip-purchase-cta';
function bind(control){
  if(!control||control.dataset.kbOpticalLightBound==='1')return;
  control.dataset.kbOpticalLightBound='1';
  var frame=0,lastEvent=null;
  function render(){
    frame=0;
    if(!lastEvent)return;
    var rect=control.getBoundingClientRect();
    if(!rect.width||!rect.height)return;
    var x=Math.max(0,Math.min(100,(lastEvent.clientX-rect.left)/rect.width*100));
    var y=Math.max(-20,Math.min(120,(lastEvent.clientY-rect.top)/rect.height*100));
    control.style.setProperty('--kb-light-x',x.toFixed(1)+'%');
    control.style.setProperty('--kb-light-y',y.toFixed(1)+'%');
  }
  control.addEventListener('pointermove',function(event){
    lastEvent=event;
    if(!frame)frame=requestAnimationFrame(render);
  },{passive:true});
  control.addEventListener('pointerleave',function(){
    lastEvent=null;
    if(frame){cancelAnimationFrame(frame);frame=0}
    control.style.removeProperty('--kb-light-x');
    control.style.removeProperty('--kb-light-y');
  },{passive:true});
}
document.addEventListener('pointerover',function(event){
  var target=event.target instanceof Element?event.target.closest(selector):null;
  if(target)bind(target);
},{passive:true});
})();
